public struct ArtifactFetchRequest {
    public var logicalPath: String
    public var expectedSha256: String
    public var candidateUrls: [String]
    public var maximumBytes: UInt64
    public var redirectsAllowed: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(logicalPath: String, expectedSha256: String, candidateUrls: [String], maximumBytes: UInt64, redirectsAllowed: Bool) {
        self.logicalPath = logicalPath
        self.expectedSha256 = expectedSha256
        self.candidateUrls = candidateUrls
        self.maximumBytes = maximumBytes
        self.redirectsAllowed = redirectsAllowed
    }
}

#if compiler(>=6)
extension ArtifactFetchRequest: Sendable {}
#endif


extension ArtifactFetchRequest: Equatable, Hashable {
    public static func ==(lhs: ArtifactFetchRequest, rhs: ArtifactFetchRequest) -> Bool {
        if lhs.logicalPath != rhs.logicalPath {
            return false
        }
        if lhs.expectedSha256 != rhs.expectedSha256 {
            return false
        }
        if lhs.candidateUrls != rhs.candidateUrls {
            return false
        }
        if lhs.maximumBytes != rhs.maximumBytes {
            return false
        }
        if lhs.redirectsAllowed != rhs.redirectsAllowed {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(logicalPath)
        hasher.combine(expectedSha256)
        hasher.combine(candidateUrls)
        hasher.combine(maximumBytes)
        hasher.combine(redirectsAllowed)
    }
}



